在ARC环境下这段代码为什么不会崩溃？<br /> <pre class="prettyprint lang-cpp">@property(nonatomic, weak) void(^block)();

- (void)viewDidLoad {
[super viewDidLoad];

void(^ __weak blockA)() = ^{
NSLog(@&quot;just a block&quot;);
};
_block = blockA;
}

- (IBAction)action:(id)sender {
_block();
}</pre> <br /> <br /> <div>  <br /> </div>

代码的正确输出是()<br /> <pre class="prettyprint lang-cpp">- (void)viewDidLoad
 {
 [super viewDidLoad];
 NSLog(@&quot;1&quot;);
 dispatch_sync(dispatch_get_main_queue(), ^{
 NSLog(@&quot;2&quot;);
 });
 NSLog(@&quot;3&quot;);
 }</pre> <div>  <br /> </div>

